    ! * -> LNGDG3ChargeLowSoC : if [PL > Ppv + Pw && SoC <= 0.2 && PL - Ppv - Pw > Pgmax && PL - Ppv - Pw + Pd1max / 10.0 <= Pgmax + eng3_Pmax];
