            LNG_cut_in = 0;
            LNG_cut_out = 1;
            DG3_cut_in = 0;
            DG3_cut_out = 1;
            DG1_cut_in = 0;
            DG1_cut_out = 1;
            DG2_cut_in = 0;
            DG2_cut_out = 1;
            Load_cut_in = 1;
